import { existsSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';

import { matchesAnyPattern } from '../../src/features/plugins/sites/matchPattern';
import type { PluginManifest } from '../../src/features/plugins/types';
import { compareStrings } from './pluginChecks';

/** Revocations use the official id namespace generated by plugin:new. */
export function readSiteRevocations(
  catalogDir: string,
  siteDir: string,
  plugins: readonly PluginManifest[],
): readonly string[] {
  const path = join(catalogDir, 'sites', siteDir, 'revoked.json');
  if (!existsSync(path)) return [];
  const displayPath = relative(catalogDir, path);
  const raw: unknown = JSON.parse(readFileSync(path, 'utf8'));
  if (!Array.isArray(raw)) throw new Error(`${displayPath}: must be an array`);
  const ids = new Set<string>();
  const live = new Set(plugins.map((plugin) => plugin.id));
  const prefix = `voyager.${siteDir}-`;
  for (const [index, entry] of raw.entries()) {
    const location = `${displayPath}[${index}]`;
    if (
      typeof entry !== 'object' ||
      entry === null ||
      Array.isArray(entry) ||
      typeof entry.id !== 'string' ||
      !entry.id.startsWith(prefix) ||
      !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(entry.id.slice(prefix.length))
    ) {
      throw new Error(`${location}: id must be in the ${prefix}<kebab-case> namespace`);
    }
    if (typeof entry.reason !== 'string' || entry.reason.trim() === '') {
      throw new Error(`${location}: reason must be a non-empty string`);
    }
    if (ids.has(entry.id)) throw new Error(`${location}: duplicate revoked id ${entry.id}`);
    if (live.has(entry.id)) throw new Error(`${location}: ${entry.id} is still a live plugin`);
    ids.add(entry.id);
  }
  return [...ids].sort(compareStrings);
}

/**
 * Whether any of a plugin's patterns reaches `host`, whatever its path: a plugin scoped to
 * `/c/*` still runs on that host, so it must not be revoked there.
 */
export function pluginCoversHost(matches: readonly string[], host: string): boolean {
  const hostWide = matches.map((pattern) => pattern.replace(/^([a-z*]+:\/\/[^/]+)\/.*$/, '$1/*'));
  return matchesAnyPattern(`https://${host}/`, hostWide);
}
